+describe("view_order_reversed", () => {
+    const opt = (value: boolean) => ({
+        view_order_reversed: {
+            value,
+            default: false,
+            help: "",
+            type: "bool",
+        },
+    });
+    const add = (s, id: string) =>
+        reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id },
+                matching_filters: {},
+            }),
+        );
+
+    it("is read from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        // @ts-expect-error partial options are sufficient here
+        let s = reduceFlows(undefined, OPTIONS_RECEIVE(opt(true)));
+        expect(s.viewOrderReversed).toBe(true);
+        s = reduceFlows(s, OPTIONS_UPDATE(opt(false)));
+        expect(s.viewOrderReversed).toBe(false);
+        expect(reduceFlows(s, OPTIONS_UPDATE({}))).toBe(s);
+    });
+
+    it("inserts new flows at the front when reversed", () => {
+        let s = reduceFlows(undefined, OPTIONS_UPDATE(opt(true)));
+        s = add(add(s, "a"), "b");
+        expect(s.view.map((f) => f.id)).toEqual(["b", "a"]);
+        expect(s._viewIndex.get("b")).toBe(0);
+        expect(s._viewIndex.get("a")).toBe(1);
+    });
+
+    it("inserts new flows at the back when not reversed", () => {
+        const s = add(add(reduceFlows(undefined, { type: "" }), "a"), "b");
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b"]);
+    });
+
+    it("yields to an active column sort", () => {
+        let s = reduceFlows(undefined, OPTIONS_UPDATE(opt(true)));
+        s = reduceFlows(s, flowActions.setSort({ column: "path", desc: false }));
+        s = add(s, "a");
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id: "b" },
+                matching_filters: {},
+            }),
+        );
+        // Equal sort keys: sorted insertion appends rather than prepends.
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b"]);
+    });
+});
